const KEY='tea-diary-v1', $=s=>document.querySelector(s), baseCategories=['鲜奶茶','传统奶茶','果茶','纯茶','其他'];
const dateKey=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const parseDate=s=>new Date(s+'T12:00:00');
function monday(d){const x=new Date(d);x.setHours(12,0,0,0);x.setDate(x.getDate()-(x.getDay()+6)%7);return x}
function offset(d,n){const x=new Date(d);x.setDate(x.getDate()+n);return x}
function validRecord(r){return r&&typeof r.id==='string'&&typeof r.date==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(r.date)&&!isNaN(parseDate(r.date))&&dateKey(parseDate(r.date))===r.date&&typeof r.category==='string'&&r.category.trim().length>0&&r.category.length<=20&&['name','brand','sugar','ice','note'].every(k=>typeof r[k]==='string'&&r[k].length<=200)}
let records=[],week=monday(new Date()),selected=null,storageProblem=false;
try{const raw=localStorage.getItem(KEY);if(raw){const data=JSON.parse(raw);if(!Array.isArray(data)||!data.every(validRecord))throw Error();records=data}}catch{storageProblem=true}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function persist(next){try{localStorage.setItem(KEY,JSON.stringify(next));records=next;return true}catch{toast('保存失败：浏览器存储不可用，请先导出备份。');return false}}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function render(){const start=dateKey(week),end=dateKey(offset(week,6)),items=records.filter(r=>r.date>=start&&r.date<=end),counts={};items.forEach(r=>counts[r.category]=(counts[r.category]||0)+1);const ranked=Object.entries(counts).sort((a,b)=>b[1]-a[1]);$('#range').textContent=`${week.getFullYear()} 年 ${week.getMonth()+1} 月 ${week.getDate()} 日 — ${offset(week,6).getMonth()+1} 月 ${offset(week,6).getDate()} 日`;$('#week-badge').textContent=start===dateKey(monday(new Date()))?'本周':'周记';$('#total').textContent=items.length;$('#types').textContent=ranked.length;$('#favorite').textContent=ranked[0]?.[0]||'等待第一杯';$('#favorite-note').textContent=ranked.length?`这一周，${ranked[0][1]} 次选择了它`:'你的偏爱，会在这里出现';$('#calendar').innerHTML=Array.from({length:7},(_,i)=>{const d=offset(week,i),key=dateKey(d),n=items.filter(r=>r.date===key).length;return `<button class="day ${key===dateKey(new Date())?'today':''} ${selected===key?'selected':''} ${n?'has':''}" data-date="${key}" aria-pressed="${selected===key}"><span class="dow">周${'一二三四五六日'[i]}</span><span class="date">${d.getDate()}</span><span class="day-cup" aria-hidden="true">${n?'🥤':'♧'}</span><span class="day-count">${n?n+' 杯快乐':'等一杯甜'}</span></button>`}).join('');$('#list-title').textContent=selected?`${parseDate(selected).getMonth()+1} 月 ${parseDate(selected).getDate()} 日的奶茶`:'本周的奶茶清单';const shown=items.filter(r=>!selected||r.date===selected).sort((a,b)=>b.date.localeCompare(a.date));$('#records').innerHTML=shown.length?shown.map(r=>`<button class="record" data-id="${esc(r.id)}" aria-label="编辑 ${esc(r.name||r.category)}"><span class="record-icon">🥤</span><span class="record-body"><span class="record-name">${esc(r.name||r.category)}${r.brand?' · '+esc(r.brand):''}</span><span class="record-meta" style="display:block">${r.date.slice(5).replace('-',' / ')}${[r.sugar,r.ice].filter(v=>v&&v!=='未选择').map(v=>' · '+esc(v)).join('')}${r.note?' · '+esc(r.note):''}</span></span><span class="tag">${esc(r.category)}</span></button>`).join(''):`<div class="empty"><span class="empty-icon">♧</span>${selected?'这一天，留一点甜给自己':'这一周的第一杯，会是什么呢？'}<p>记下你的奶茶，让快乐有迹可循。</p></div>`;$('#chart').innerHTML=ranked.length?ranked.map(([c,n],i)=>`<div class="chart-row"><div class="chart-label"><span>${esc(c)}</span><span>${n} 杯 · ${Math.round(n/items.length*100)}%</span></div><div class="bar-track"><div class="bar" style="width:${n/items.length*100}%;background:${['#cfc0e3','#bcd8e6','#eddda5'][i%3]}"></div></div></div>`).join(''):'<div class="empty"><span class="empty-icon"><svg class="asterisk-icon" viewBox="0 0 32 32" aria-hidden="true" focusable="false"><path d="M16 3v26M3 16h26M7 7l18 18M7 25L25 7" fill="none" stroke="currentColor" stroke-width="4" stroke-linecap="round"/></svg></span><p>喝过的每一种味道<br>都会在这里留下印记</p></div>'}
function openForm(id){const f=$('#form');f.reset();const r=records.find(x=>x.id===id);const categories=[...new Set([...baseCategories,...records.map(r=>r.category)])];f.elements.category.innerHTML=categories.map(c=>`<option>${esc(c)}</option>`).join('')+'<option value="__custom">＋ 自定义品类</option>';f.elements.id.value=r?.id||'';f.elements.date.value=r?.date||selected||(dateKey(week)===dateKey(monday(new Date()))?dateKey(new Date()):dateKey(week));if(r)for(const k of ['name','brand','sugar','ice','note','category'])f.elements[k].value=r[k];$('#custom-label').hidden=true;f.elements.custom.required=false;$('#delete').hidden=!r;$('#modal-title').textContent=r?'编辑这杯小快乐':'记一杯小快乐';$('#dialog').showModal()}
$('#add').onclick=()=>openForm();$('#add-bottom').onclick=()=>openForm();$('#close').onclick=()=>$('#dialog').close();$('#calendar').onclick=e=>{const b=e.target.closest('[data-date]');if(b){selected=selected===b.dataset.date?null:b.dataset.date;render()}};$('#records').onclick=e=>{const b=e.target.closest('[data-id]');if(b)openForm(b.dataset.id)};$('#all').onclick=()=>{selected=null;render()};$('#prev').onclick=()=>{week=offset(week,-7);selected=null;render()};$('#next').onclick=()=>{week=offset(week,7);selected=null;render()};$('#today').onclick=()=>{week=monday(new Date());selected=null;render()};$('#form').elements.category.onchange=e=>{const custom=e.target.value==='__custom';$('#custom-label').hidden=!custom;$('#form').elements.custom.required=custom;if(custom)$('#form').elements.custom.focus()};
$('#form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));const r={id:d.id||crypto.randomUUID(),date:d.date,category:(d.category==='__custom'?d.custom:d.category).trim(),brand:d.brand.trim(),name:d.name.trim(),sugar:d.sugar,ice:d.ice,note:d.note.trim()};if(!validRecord(r)){toast('请填写有效日期和品类。');return}const next=records.filter(x=>x.id!==r.id).concat(r);if(persist(next)){week=monday(parseDate(r.date));selected=null;render();$('#dialog').close();toast('这杯小快乐，记下啦 ♡')}};
$('#delete').onclick=()=>{if(confirm('确定删除这杯记录吗？')){if(persist(records.filter(r=>r.id!==$('#form').elements.id.value))){$('#dialog').close();render();toast('这杯记录已删除')}}};
$('#export').onclick=()=>{const blob=new Blob([JSON.stringify({version:1,records},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`奶茶周记-${dateKey(new Date())}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('备份已导出，记得妥善保存')};$('#import').onclick=()=>$('#file').click();$('#file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5e6)throw Error();const data=JSON.parse(await file.text());if(data.version!==1||!Array.isArray(data.records)||!data.records.every(validRecord))throw Error();const incoming=new Map(records.map(r=>[r.id,r]));let added=0;data.records.forEach(r=>{if(!incoming.has(r.id)){incoming.set(r.id,r);added++}});if(persist([...incoming.values()])){render();toast(`导入成功，新增 ${added} 杯记录（重复记录已跳过）`)}}catch{toast('无法导入，请选择有效的奶茶周记 JSON 备份。')}finally{e.target.value=''}};window.addEventListener('storage',e=>{if(e.key===KEY){try{const data=JSON.parse(e.newValue||'[]');if(Array.isArray(data)&&data.every(validRecord)){records=data;render()}}catch{}}});render();if(storageProblem)toast('原有数据无法读取，请保留备份后再添加记录。');
